import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
out = Path(__file__).parent
data = json.loads((ROOT/'apps/mobile_app/assets/data/launch_trades.json').read_text(encoding='utf-8'))['trades']
resources = {lang: {} for lang in ('en','hi','mr')}

def add_select(key, rows):
    for lang in resources:
        body = ' '.join(f'{ident} {{{values[lang]}}}' for ident, values in rows.items())
        resources[lang][key] = '{id, select, '+body+' other {{fallback}}}'
        resources[lang]['@'+key] = {'placeholders': {'id': {'type':'String'}, 'fallback': {'type':'String'}}}

