names,taglines = {},{}
by_id = {x['tradeId']:x for x in data}
for line in trade_rows.splitlines():
    ident,hi,mr,hit,mrt = line.split('|')
    names[ident]={'en':by_id[ident]['name'],'hi':hi,'mr':mr}
    taglines[ident]={'en':by_id[ident]['tagline'],'hi':hit,'mr':mrt}
add_select('catalogTradeName',names)
add_select('catalogTradeTagline',taglines)

